TEMPLATES = ('Что такое {nom}?', 'Расскажи о {prep}.', 'Объясни коротко, что известно о {prep}.', 'А как насчёт вопроса: {nom}, что это?')
FOLLOW = 'А почему так?'


def build_material():
    """``(text, facts)``; each fact is ``(subject, nom, prep, marker)``. 10 sections per subject, each ~650 characters, subjects one after another."""
    out, facts = [], []
    for name, data in SUBJECTS.items():
        out.append(f'# Курс: {name}\n')
        for i, (nom, prep, sentence, marker) in enumerate(data['facts']):
            filler = [data['filler'][(i + k) % 4] for k in range(7)]
            out.append(f'## Раздел {i + 1}. {nom[:1].upper() + nom[1:]}\n\n' + filler[0] + ' ' + filler[1] + '\n\n' + sentence + '\n\n' + ' '.join(filler[2:]) + '\n')
            facts.append((name, nom, prep, marker))
    return '\n'.join(out), facts


def questions():
    """200 ``(question, history, marker)``: 4 templates + 1 follow-up with the topic only in history, for each of 40 facts."""
    _, facts = build_material()
    rows = []
    for _subject, nom, prep, marker in facts:
        for tpl in TEMPLATES:
            rows.append((tpl.format(nom=nom, prep=prep), [], marker))
        rows.append((FOLLOW, [{'question': f'Расскажи о {prep}.', 'answer': 'Коротко.'}], marker))
    return rows
